const buildExcelItemWithoutVacuum=buildExcelItem;buildExcelItem=async function(wb,e,item,itemIndex,equipmentIndex){await buildExcelItemWithoutVacuum(wb,e,item,itemIndex,equipmentIndex);if(isVacuumPumpItem(e,item))await buildExcelVacuumSupplement(wb,e,item,itemIndex,equipmentIndex)};

function usePhoneCamera(n=navigator){return !!(n.userAgentData?.mobile||/Android|iPhone|iPad|iPod/i.test(n.userAgent)||(n.platform==='MacIntel'&&n.maxTouchPoints>1))}
function openPhotoPicker(slot){
 const target=equip(),index=slot.dataset.photoSlot,isEquipmentPhoto=slot.hasAttribute('data-equipment-photo');
 const dlg=document.createElement('dialog');dlg.className='rePhotoDialog';
 dlg.innerHTML=`<div class="rePhotoDialogBody"><h3>사진 첨부</h3><p>해당 칸에 넣을 사진을 선택하세요.</p><button type="button" data-source="gallery">사진 선택 · 갤러리 / 파일</button><button type="button" data-source="camera">카메라로 촬영</button><div class="reCamera" hidden><video autoplay muted playsinline></video><button type="button" data-shutter disabled>촬영하여 첨부</button></div><p role="status" class="reCameraMessage"></p><button type="button" data-close>취소</button></div>`;
 document.body.appendChild(dlg);let stream=null,closed=false;
 function cleanup(){closed=true;stream?.getTracks().forEach(t=>t.stop());dlg.remove();if(slot.isConnected)slot.focus()}
 dlg.addEventListener('close',cleanup,{once:true});dlg.querySelector('[data-close]').onclick=()=>dlg.close();
 function choose(capture){const input=document.createElement('input');input.type='file';input.accept='image/*';input.hidden=true;if(capture)input.setAttribute('capture','environment');dlg.appendChild(input);input.onchange=()=>{const f=input.files[0];if(!f){input.remove();return}(isEquipmentPhoto?equipmentPhoto:photo)({files:[f],dataset:{photo:index}},target);dlg.close()};input.addEventListener('cancel',()=>input.remove(),{once:true});input.click()}
 dlg.querySelector('[data-source="gallery"]').onclick=()=>choose(false);
 if(usePhoneCamera()){
  dlg.querySelector('[data-source="camera"]').textContent='휴대폰 카메라로 촬영';
  dlg.querySelector('.reCameraMessage').textContent='휴대폰 촬영 화면에서 방향과 줌을 조절한 뒤 사진 사용 또는 완료를 선택하세요.';
 }
 dlg.querySelector('[data-source="camera"]').onclick=async()=>{
  if(usePhoneCamera()){choose(true);return} 
  const msg=dlg.querySelector('.reCameraMessage');
  if(!navigator.mediaDevices?.getUserMedia){msg.textContent='이 환경에서는 카메라를 열 수 없습니다. HTTPS로 접속하거나 사진 선택을 이용하세요.';return}
  const cam=dlg.querySelector('[data-source="camera"]');cam.disabled=true;msg.textContent='카메라 연결 중…';
  try{const incoming=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});if(closed){incoming.getTracks().forEach(t=>t.stop());return}stream=incoming;const video=dlg.querySelector('video');video.muted=true;video.autoplay=true;video.playsInline=true;video.setAttribute('webkit-playsinline','');video.srcObject=stream;dlg.querySelector('.reCamera').hidden=false;
   await cameraPreviewReady(video,()=>closed);
   if(closed)return;dlg.querySelector('[data-shutter]').disabled=false;msg.textContent='영상이 보이는지 확인한 뒤 촬영하여 첨부를 누르세요.';
  }catch(err){stream?.getTracks().forEach(t=>t.stop());if(!closed){dlg.querySelector('[data-shutter]').disabled=true;dlg.querySelector('.reCamera').hidden=true;const messages={NotAllowedError:'카메라 사용이 허용되지 않았습니다. 브라우저의 사이트 카메라 권한을 허용해 주세요.',NotFoundError:'사용할 수 있는 카메라를 찾지 못했습니다.',NotReadableError:'카메라를 사용할 수 없습니다. 다른 촬영 앱을 닫고 다시 시도해 주세요.',PreviewTimeout:'카메라 영상이 도착하지 않았습니다. 다시 시도하거나 기본 카메라 앱으로 촬영 후 사진 선택으로 첨부해 주세요.'};msg.textContent=messages[err.name]||'카메라를 열지 못했습니다. 권한과 연결을 확인하거나 사진 선택으로 첨부해 주세요.';cam.disabled=false;cam.textContent='카메라 다시 연결'}}
 };
 dlg.querySelector('[data-shutter]').onclick=()=>{const video=dlg.querySelector('video');if(!video.videoWidth)return;const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{if(!blob||closed)return;(isEquipmentPhoto?equipmentPhoto:photo)({files:[blob],dataset:{photo:index}},target);dlg.close()},'image/jpeg',.9)};
 dlg.showModal();
}

function cameraPreviewReady(video,isClosed){
 return new Promise((resolve,reject)=>{
  let done=false,timer;
  function finish(error){if(done)return;done=true;clearInterval(timer);error?reject(error):resolve()}
  const started=Date.now();
  timer=setInterval(()=>{if(isClosed())return finish(Object.assign(new Error('닫힘'),{name:'AbortError'}));if(video.readyState>=2&&video.videoWidth>0&&video.videoHeight>0&&!video.paused)return finish();if(Date.now()-started>12000)finish(Object.assign(new Error('영상 대기 시간 초과'),{name:'PreviewTimeout'}))},100);
  video.play().catch(finish);
 });
}

async function photo(el,target=equip()){const f=el.files[0];if(!f)return;const e=target,[i,j]=el.dataset.photo.split(':').map(Number);try{const bm=await createImageBitmap(f,{imageOrientation:'from-image'}),scale=Math.min(1,1600/Math.max(bm.width,bm.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bm.width*scale);canvas.height=Math.round(bm.height*scale);canvas.getContext('2d').drawImage(bm,0,0,canvas.width,canvas.height);e.items[i].photos[j]=canvas.toDataURL('image/jpeg',.85);bm.close();await save();render()}catch(err){alert('사진을 처리하지 못했습니다. JPG 또는 PNG 파일과 저장공간을 확인하세요.')}}
async function equipmentPhoto(el,target=equip()){const f=el.files[0];if(!f||!target)return;try{const bm=await createImageBitmap(f,{imageOrientation:'from-image'}),scale=Math.min(1,1800/Math.max(bm.width,bm.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bm.width*scale);canvas.height=Math.round(bm.height*scale);canvas.getContext('2d').drawImage(bm,0,0,canvas.width,canvas.height);target.sitePhoto=canvas.toDataURL('image/jpeg',.88);bm.close();await save();render()}catch(err){alert('현장사진을 처리하지 못했습니다. JPG 또는 PNG 파일과 저장공간을 확인하세요.')}}
async function restore(ev){try{const v=JSON.parse(await ev.target.files[0].text());if(v.version!==2||!v.info||!Array.isArray(v.equipment)||!Array.isArray(v.energy)||v.equipment.some(e=>!e.uid||!e.number||!e.type||!Array.isArray(e.items)||e.items.some(i=>!Array.isArray(i.photos)||i.photos.some(p=>p&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p)))))throw Error();if(!confirm('현재 작성 내용을 백업 파일로 교체할까요?'))return;d=v;selected=d.equipment[0]?.uid||'';await save();render()}catch(e){alert('올바른 보고서 백업 파일인지 확인하세요.')}}
function table(rows){return '<table>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+E(v).replace(/\n/g,'<br>')+'</td>').join('')+'</tr>').join('')+'</table>'}
function textSections(n){return fields[n].map(k=>'<h3>'+E(k)+'</h3><p>'+E(d.info[k]||'미입력').replace(/\n/g,'<br>')+'</p>').join('')}
function page(title,content){return `<section class="paper"><div class="paperhead">${E(d.info['현장명']||'현장명 미입력')} · 기계설비 성능점검 보고서</div><h2>${title}</h2>${content}</section>`}
function report(){let html=page('기계설비 성능점검 보고서',table(fields[0].filter(k=>k!=='제출문').map(k=>[k,d.info[k]||'미입력'])));html+=page('점검완료 제출문','<p>'+E(d.info['제출문']||'미입력').replace(/\n/g,'<br>')+'</p>');html+=page('목차','<ol>'+titles.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol>');html+=page('Ⅰ. 성능점검 계획서',textSections(1)+ '<h3>점검대상 기계설비 수량</h3>'+table([['설비종류','등록대수'],...Object.keys(CHECK_TEMPLATES).filter(t=>d.equipment.some(e=>e.type===t)).map(t=>[t,d.equipment.filter(e=>e.type===t).length])])+'<h3>설비 현황</h3>'+table([['종류','번호','용도','설치위치'],...d.equipment.map(e=>[e.type,e.number,e['용도'],e['설치위치']]) ]));html+=page('Ⅱ. 성능점검 결과보고서',textSections(2)+table([['종류','번호','전체항목','작성항목','미흡·조치필요'],...d.equipment.map(e=>[e.type,e.number,e.items.length,e.items.filter(i=>i.result!=='미작성').length,e.items.filter(i=>['미흡','조치필요'].includes(i.result)).length]) ]));for(const e of d.equipment){html+=page(`Ⅲ. ${E(e.type)} 성능점검표 · ${E(e.number)}`,table([['설비번호',e.number],...['용도','설치위치','제조사','설치년도','사양','점검일','점검자','측정값'].map(k=>[k,e[k]||'미입력'])])+table([['점검항목','판정'],...e.items.map(i=>[i.title,i.result])]));for(const i of e.items){html+=page(`${E(e.type)} · ${E(e.number)} / ${E(i.title)}`,table([['점검방법·기준',i.criteria],['판정',i.result],['측정값·확인내용',i.measurement||'미입력']])+`<div class="photos">${['현황','적합','미흡사항'].map((name,j)=>`<section><h4>${name} 사진</h4>${i.photos[j]?`<div class="reportPhotoFrame"><img src="${i.photos[j]}" alt="${name}"></div>`:'<div class="noPhoto">사진 미첨부</div>'}<p>사유: ${E(i['reason'+j]||'미입력').replace(/\n/g,'<br>')}</p></section>`).join('')}</div>`+table([['조치사항',i.action||'미입력']]))}}html+=page('Ⅳ. 기계설비 시스템 검토',textSections(4));html+=page('Ⅴ. 성능개선 계획 수립',textSections(5)+table([['설비번호','점검항목','판정','조치사항'],...d.equipment.flatMap(e=>e.items.filter(i=>['미흡','조치필요'].includes(i.result)).map(i=>[e.number,i.title,i.result,i.action]))]));html+=page('Ⅵ. 에너지사용량 분석',textSections(6).split('<h3>에너지 절감 방안</h3>')[0]+table([['월','사용량'],...Array.from({length:12},(_,i)=>[i+1,d.energy[i]??'미입력']),['입력월 합계',d.energy.reduce((s,x)=>s+(Number(x)||0),0)]]));html+=page('Ⅶ. 에너지 절감 방안','<p>'+E(d.info['에너지 절감 방안']||'미입력').replace(/\n/g,'<br>')+'</p>');return html}
