function officialPhoto(src,label){return src?`<div class="officialPhoto"><img src="${src}" alt="${E(label)}"></div>`:`<div class="officialPhoto noPhoto">사진 미첨부</div>`}
function officialSummaryPage(e){const startPhoto=e.items.flatMap(item=>item.photos||[]).find(Boolean)||'';return `<section class="paper officialPage">${officialHeader()}<h1 class="officialTitle">${E(e.type)} 성능점검표</h1><table class="officialMeta"><tr><th>점검자</th><td>${E(e['점검자']||d.info['점검자']||'')}</td><th>점검일자</th><td>${E(e['점검일']||d.info['점검시작일']||'')}</td><th>설비번호</th><td>${E(e.number)}</td></tr><tr><th>설치위치<br>(No.)</th><td colspan="5">${E(e['설치위치']||'')}</td></tr></table><table class="officialSummary"><thead><tr><th style="width:9%">구분</th><th>점검내용</th><th style="width:12%">점검결과</th></tr></thead><tbody>${e.items.map((item,index)=>`<tr><td class="group">${index===0?'점검<br>항목':''}</td><td>${E(item.title)}</td><td class="mark">${resultMark(item.result)}</td></tr>`).join('')}</tbody></table><div class="officialAction"><b>&lt; 미흡사항 &gt;</b><br>${E(e.items.filter(item=>item.result==='미흡').map(item=>item.title).join(', '))}</div><div class="officialAction"><b>&lt; 조치필요사항 &gt;</b><br>${E(e.items.filter(item=>item.result==='조치필요').map(item=>`${item.title} ${item.action||''}`).join('\n'))}</div><table class="officialGrid"><tr><th style="width:9%">현장<br>사진</th><td><div class="officialRepresentative">${startPhoto?`<img src="${startPhoto}" alt="현장 대표 사진">`:'사진 미첨부'}</div></td></tr><tr><th>비고</th><td>${E(e['측정값']||'')}</td></tr></table><div class="officialNotes"><b>작성방법</b><br>1. 유지관리지침서와 성능점검 대상 현황표를 참고하여 점검결과를 작성합니다.<br>2. 점검결과에는 적합 ○, 조치필요 ×, 해당없음 /를 표기합니다.<br>3. 현황사진에는 측정사진과 측정데이터를 포함합니다.</div>${officialFooter()}</section>`}
function officialItemPage(e,item,index){const long=String(item.criteria||'').length>500;const vacuum=isVacuumPumpItem(e,item)&&item.photos?.slice(3).some(Boolean);return `<section class="paper officialPage">${officialHeader()}<h2 class="officialItemTitle">${E(item.title)}</h2><table class="officialGrid"><tr><th style="width:9%">구분</th><th>점검내용</th></tr><tr><th>점검<br>방법·기준</th><td class="officialCriteria ${long?'long':''}">${E(item.criteria||'').replace(/\n/g,'<br>')}</td></tr></table><div class="officialPhotoGrid">${['현황 사진','적합','미흡사항'].map((label,photoIndex)=>`<section class="officialPhotoCell"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex],label)}<div class="officialReason">${photoIndex===0?'':`사유 : ${E(reasonValue(item,'reason'+photoIndex)).replace(/\n/g,'<br>')}`}</div></section>`).join('')}</div>${vacuum?`<div class="officialVacuum"><b>진공펌프 추가 사진</b><div class="officialPhotoGrid">${['진공펌프 현황사진','진공펌프 적합 사진','진공펌프 미흡사항 사진'].map((label,photoIndex)=>`<section class="officialPhotoCell"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex+3],label)}</section>`).join('')}</div></div>`:''}<table class="officialGrid officialMeasure"><tr><th style="width:18%">판정</th><td>${E(item.result||'미작성')} ${resultMark(item.result)}</td></tr><tr><th>측정값 / 확인내용</th><td>${E(item.measurement||'').replace(/\n/g,'<br>')}</td></tr><tr><th>조치사항</th><td>${E(item.action||'').replace(/\n/g,'<br>')}</td></tr></table>${officialFooter()}</section>`}
function officialReport(){let html=page('기계설비 성능점검 보고서',table(fields[0].filter(k=>k!=='제출문').map(k=>[k,d.info[k]||'미입력'])));html+=page('점검완료 제출문','<p>'+E(d.info['제출문']||'미입력').replace(/\n/g,'<br>')+'</p>');html+=page('목차','<ol>'+titles.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol>');html+=page('Ⅰ. 성능점검 계획서',textSections(1));html+=page('Ⅱ. 성능점검 결과보고서',textSections(2));for(const e of d.equipment){html+=officialSummaryPage(e);e.items.forEach((item,index)=>html+=officialItemPage(e,item,index))}html+=page('Ⅳ. 기계설비 시스템 검토',textSections(4));html+=page('Ⅴ. 성능개선 계획 수립',textSections(5));html+=page('Ⅵ. 에너지사용량 분석',textSections(6));return html}
