function compactOfficialItem(e,item,index,dense){const photoHeight=dense?92:158,reasonHeight=dense?35:54,vacuum=isVacuumPumpItem(e,item)&&item.photos?.slice(3).some(Boolean);return `<section class="officialCompactBlock"><h2 class="officialItemTitle">${E(item.title)}</h2><table class="officialGrid"><tr><th style="width:9%">구분</th><th>점검내용</th></tr><tr><th>점검<br>방법·기준</th><td class="officialCriteria ${String(item.criteria||'').length>500?'long':''}" style="height:auto;max-height:${dense?'62':'115'}px;overflow:hidden">${E(item.criteria||'').replace(/\n/g,'<br>')}</td></tr></table><div class="officialPhotoGrid" style="margin-top:5px">${['현황 사진','적합','미흡사항'].map((label,photoIndex)=>`<section class="officialPhotoCell" style="grid-template-rows:20px ${photoHeight}px ${reasonHeight}px"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex],label)}<div class="officialReason">${photoIndex===0?'':`사유 : ${E(reasonValue(item,'reason'+photoIndex)).replace(/\n/g,'<br>')}`}</div></section>`).join('')}</div>${vacuum?`<div class="officialVacuum"><b>진공펌프 현황·판정 사진</b><div class="officialPhotoGrid" style="margin-top:3px">${['진공펌프 현황사진','진공펌프 적합 사진','진공펌프 미흡사항 사진'].map((label,photoIndex)=>`<section class="officialPhotoCell" style="grid-template-rows:18px 70px"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex+3],label)}</section>`).join('')}</div></div>`:''}<table class="officialGrid officialMeasure" style="margin-top:4px"><tr><th style="width:18%">판정</th><td>${E(item.result||'미작성')} ${resultMark(item.result)}</td></tr><tr><th>측정값 / 확인내용</th><td>${E(item.measurement||'').replace(/\n/g,'<br>')}</td></tr><tr><th>조치사항</th><td>${E(item.action||'').replace(/\n/g,'<br>')}</td></tr></table></section>`}
